    const taskDate = cleanDate(dateProp);
    if (taskDate && taskDate !== todayIso) return false;
    return !extractCheckbox(task);
  });

todaysTasks.sort((a, b) => extractTaskName(a).localeCompare(extractTaskName(b)));

const otherTasks = [];

todaysTasks.forEach((task) => {
  const ids = getTaskProjectIds(task);
  let matched = false;
  ids.forEach((id) => {
    if (tasksByProject.has(id)) {
      tasksByProject.get(id).push(task);
      matched = true;
    }
  });
  if (!matched) {
    otherTasks.push(task);
  }
});

const notionBlocks = [];

notionBlocks.push({
  object: 'block',
  type: 'heading_3',
  heading_3: {
    rich_text: [
      {
        type: 'text',
        text: { content: 'Projects and Tasks' },
        annotations: { bold: true },
      },
    ],
  },
});

notionBlocks.push({ object: 'block', type: 'divider', divider: {} });

if (!activeProjects.length) {
  notionBlocks.push({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: { content: 'No active projects found.' },
          annotations: { italic: true },
        },
      ],
    },
  });
} else {
  const sortedProjects = [...activeProjects].sort((a, b) =>
    extractProjectName(a).localeCompare(extractProjectName(b)),
  );

  sortedProjects.forEach((project) => {
    const projectId = extractProjectId(project);
    const name = extractProjectName(project);
    const detailsText = projectDetails(project);
    const projectTasks = projectId ? tasksByProject.get(projectId) || [] : [];

    const projectBlock = {
      object: 'block',
      type: 'bulleted_list_item',
      bulleted_list_item: {
        rich_text: [
          {
            type: 'text',
            text: {
              content: name,
              link: project?.url ? { url: project.url } : undefined,
            },
            annotations: { bold: true },
          },
        ],
      },
    };

    if (detailsText) {
      projectBlock.bulleted_list_item.rich_text.push({
        type: 'text',
        text: { content: detailsText },
      });
    }

    const childTasks = projectTasks.length
      ? projectTasks.map(createTaskBlock)
      : [
          {
            object: 'block',
            type: 'bulleted_list_item',
            bulleted_list_item: {
              rich_text: [
                {
                  type: 'text',
                  text: { content: 'No tasks scheduled for today.' },
                  annotations: { italic: true },
                },
              ],
            },
          },
        ];

    projectBlock.children = childTasks;
    notionBlocks.push(projectBlock);
  });
}

notionBlocks.push({ object: 'block', type: 'divider', divider: {} });

notionBlocks.push({
  object: 'block',
  type: 'heading_3',
  heading_3: {
    rich_text: [
      {
        type: 'text',
        text: { content: 'Other Tasks' },
        annotations: { bold: true },
      },
    ],
  },
});

if (!otherTasks.length) {
  notionBlocks.push({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: { content: 'No other tasks scheduled for today.' },
          annotations: { italic: true },
        },
      ],
    },
  });
} else {
  otherTasks.forEach((task) => {
    notionBlocks.push(createTaskBlock(task));
  });
}

return JSON.stringify({ children: notionBlocks });
```

